# Apply neighbor-based transformation: 8 with ANY different neighbor becomes 1

def neighbor_transform(grid):
    """If a cell (row,col) with value 8 has ANY neighbor with different value, change to 1"""
    H, W = len(grid), len(grid[0])
    result = [[0]*W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0:
                result[r][c] = 0  # Zeros never change
            else:  # It's 8
                # Check all 4 neighbors
                has_diff = False

                # Left neighbor
                if c > 0 and grid[r][c-1] != grid[r][c]:
                    has_diff = True
                # Right neighbor
                elif c < W-1 and grid[r][c+1] != grid[r][c]:
                    has_diff = True
                # Up neighbor
                elif r > 0 and grid[r-1][c] != grid[r][c]:
                    has_diff = True
                # Down neighbor
                elif r < H-1 and grid[r+1][c] != grid[r][c]:
                    has_diff = True

                if has_diff:
                    result[r][c] = 1
                else:
                    result[r][c] = 8

    return result

block1 = [
    [0, 0, 8, 0, 0, 8, 0, 0, 8, 0, 0, 8, 8, 8, 8, 8, 0, 0, 8, 8, 0, 0, 0],
    [8, 0, 8, 8, 0, 8, 8, 0, 8, 8, 0, 8, 8, 8, 8, 8, 8, 0, 8, 0, 0, 0, 0]
]
