h, w = len(arr), len(arr[0])

def find_l_shapes(grid):
    shapes = []
    for r in range(h-1):
        for c in range(w-1):
            tl, tr, bl, br = grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]
            nonzero = sum(1 for x in [tl,tr,bl,br] if x != 0)
            if nonzero == 3:
                if grid[r][c] == 0:
                    missing = 'TL'
                elif grid[r][c+1] == 0:
                    missing = 'TR'
                elif grid[r+1][c] == 0:
                    missing = 'BL'
                elif grid[r+1][c+1] == 0:
                    missing = 'BR'
                else:
                    continue
                shapes.append({'anchor': (r,c), 'missing': missing})
    return shapes

